ALTER TABLE el_employee_loan_deductions ADD COLUMN released_at INTEGER;
ALTER TABLE el_employee_loan_deductions ADD COLUMN released_by TEXT;
CREATE TABLE el_staff_payroll_cancellations(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,payroll_id TEXT NOT NULL,original_month TEXT NOT NULL,reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 5 AND 500),cancelled_by TEXT NOT NULL,cancelled_at INTEGER NOT NULL,UNIQUE(org_id,payroll_id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,payroll_id) REFERENCES el_staff_payroll(org_id,id),FOREIGN KEY(org_id,cancelled_by) REFERENCES el_memberships(org_id,user_id));
CREATE TRIGGER el_staff_payroll_cancellation_insert BEFORE INSERT ON el_staff_payroll_cancellations BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_staff_payroll p WHERE p.id=NEW.payroll_id AND p.org_id=NEW.org_id AND p.branch_id=NEW.branch_id AND p.status='draft' AND p.month=NEW.original_month AND p.accrual_journal_id IS NULL AND p.payment_journal_id IS NULL) THEN RAISE(ABORT,'Only an unapproved draft employee payroll can be cancelled') END;
END;
CREATE TRIGGER el_staff_payroll_cancellation_immutable BEFORE UPDATE ON el_staff_payroll_cancellations BEGIN SELECT RAISE(ABORT,'Employee payroll cancellations are immutable');END;
CREATE TRIGGER el_staff_payroll_cancellation_no_delete BEFORE DELETE ON el_staff_payroll_cancellations BEGIN SELECT RAISE(ABORT,'Employee payroll cancellations cannot be deleted');END;
CREATE TRIGGER el_staff_payroll_cancelled_no_approval BEFORE UPDATE OF status ON el_staff_payroll WHEN NEW.status<>OLD.status AND EXISTS(SELECT 1 FROM el_staff_payroll_cancellations WHERE payroll_id=OLD.id AND org_id=OLD.org_id) BEGIN SELECT RAISE(ABORT,'Cancelled employee payroll cannot be approved'); END;
DROP TRIGGER el_staff_payroll_guard;
CREATE TRIGGER el_staff_payroll_guard BEFORE UPDATE ON el_staff_payroll BEGIN SELECT CASE WHEN NEW.total<>OLD.total OR NEW.calculation_json<>OLD.calculation_json OR NEW.employee_id<>OLD.employee_id OR (NEW.month<>OLD.month AND NOT(OLD.status='draft' AND NEW.status='draft' AND NEW.month=OLD.month||'~cancelled-'||OLD.id AND EXISTS(SELECT 1 FROM el_staff_payroll_cancellations c WHERE c.payroll_id=OLD.id AND c.org_id=OLD.org_id AND c.original_month=OLD.month))) OR NEW.contract_id<>OLD.contract_id THEN RAISE(ABORT,'Employee payroll calculation is immutable') END;SELECT CASE WHEN NOT((OLD.status='draft' AND NEW.status='approved' AND NEW.approved_by<>OLD.created_by) OR (OLD.status='approved' AND NEW.status='paid' AND NEW.paid_by<>OLD.created_by AND NEW.paid_by<>OLD.approved_by) OR (OLD.status='draft' AND NEW.status='draft' AND NEW.month<>OLD.month)) THEN RAISE(ABORT,'Employee payroll requires separate preparer approver and payer') END;END;
DROP TRIGGER el_employee_loan_recovery_guard;
CREATE TRIGGER el_employee_loan_recovery_guard BEFORE INSERT ON el_employee_loan_recoveries BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_employee_loans p WHERE p.id=NEW.loan_id AND p.org_id=NEW.org_id AND p.status='disbursed' AND p.currency=(SELECT currency FROM el_organizations WHERE id=p.org_id) AND NEW.date>=p.disbursed_on AND NEW.amount<=p.principal-COALESCE((SELECT sum(amount) FROM el_employee_loan_recoveries WHERE loan_id=p.id),0)-COALESCE((SELECT sum(amount) FROM el_employee_loan_deductions WHERE loan_id=p.id AND released_at IS NULL),0) AND EXISTS(SELECT 1 FROM el_journals j WHERE j.id=NEW.journal_id AND j.org_id=p.org_id AND j.branch_id=p.branch_id AND j.status='posted' AND j.date=NEW.date AND j.source_type='employee_loan_recovery' AND j.source_id=NEW.id AND (SELECT count(*) FROM el_journal_lines WHERE journal_id=j.id)=2 AND EXISTS(SELECT 1 FROM el_journal_lines l WHERE l.journal_id=j.id AND l.account_id=p.receivable_account_id AND l.debit=0 AND l.credit=NEW.amount) AND EXISTS(SELECT 1 FROM el_journal_lines l JOIN el_accounts a ON a.id=l.account_id WHERE l.journal_id=j.id AND a.org_id=p.org_id AND a.system_key=NEW.method AND l.debit=NEW.amount AND l.credit=0))) THEN RAISE(ABORT,'Employee loan recovery exceeds balance or matching journal is unavailable') END;
END;
DROP TRIGGER el_employee_loan_deduction_insert;
CREATE TRIGGER el_employee_loan_deduction_insert BEFORE INSERT ON el_employee_loan_deductions BEGIN
 SELECT CASE WHEN NEW.applied_journal_id IS NOT NULL THEN RAISE(ABORT,'Loan deduction must begin reserved') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_employee_loans l JOIN el_staff_payroll p ON p.org_id=l.org_id AND p.employee_id=l.employee_id AND p.branch_id=l.branch_id JOIN el_organizations o ON o.id=l.org_id WHERE l.id=NEW.loan_id AND l.org_id=NEW.org_id AND p.id=NEW.payroll_id AND NOT EXISTS(SELECT 1 FROM el_staff_payroll_cancellations x WHERE x.payroll_id=p.id) AND l.status='disbursed' AND p.status='draft' AND p.total>0 AND l.currency=o.currency AND NEW.amount<=l.principal-COALESCE((SELECT sum(amount) FROM el_employee_loan_recoveries WHERE loan_id=l.id),0)-COALESCE((SELECT sum(amount) FROM el_employee_loan_deductions WHERE loan_id=l.id AND released_at IS NULL),0)) THEN RAISE(ABORT,'Employee loan deduction exceeds balance or payroll is unavailable') END;
END;
DROP TRIGGER el_employee_loan_deduction_update;
CREATE TRIGGER el_employee_loan_deduction_update BEFORE UPDATE ON el_employee_loan_deductions BEGIN
 SELECT CASE WHEN NEW.id IS NOT OLD.id OR NEW.org_id IS NOT OLD.org_id OR NEW.loan_id IS NOT OLD.loan_id OR NEW.payroll_id IS NOT OLD.payroll_id OR NEW.amount IS NOT OLD.amount OR NEW.created_by IS NOT OLD.created_by OR NEW.created_at IS NOT OLD.created_at OR OLD.applied_journal_id IS NOT NULL OR OLD.released_at IS NOT NULL OR (NEW.applied_journal_id IS NULL AND NEW.released_at IS NULL) OR (NEW.applied_journal_id IS NOT NULL AND NEW.released_at IS NOT NULL) OR (NEW.released_at IS NULL AND NEW.released_by IS NOT NULL) OR (NEW.released_at IS NOT NULL AND NEW.released_by IS NULL) THEN RAISE(ABORT,'Employee loan deduction can only be applied or released once') END;
 SELECT CASE WHEN NEW.applied_journal_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM el_staff_payroll p JOIN el_employee_loans l ON l.id=NEW.loan_id AND l.org_id=p.org_id JOIN el_journals j ON j.id=NEW.applied_journal_id AND j.org_id=p.org_id WHERE p.id=NEW.payroll_id AND p.org_id=NEW.org_id AND p.status='approved' AND p.accrual_journal_id=NEW.applied_journal_id AND j.status='posted' AND j.branch_id=l.branch_id AND j.source_type='staff_payroll_accrual' AND j.source_id=p.id AND j.date>=l.disbursed_on AND EXISTS(SELECT 1 FROM el_journal_lines x WHERE x.journal_id=j.id AND x.account_id=l.receivable_account_id AND x.credit>=NEW.amount)) THEN RAISE(ABORT,'Employee loan deduction needs the matching posted payroll accrual') END;
 SELECT CASE WHEN NEW.released_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM el_staff_payroll_cancellations c JOIN el_staff_payroll p ON p.id=c.payroll_id AND p.org_id=c.org_id WHERE c.payroll_id=NEW.payroll_id AND c.org_id=NEW.org_id AND p.status='draft' AND NEW.released_by=c.cancelled_by) THEN RAISE(ABORT,'Employee loan deduction release needs a cancelled draft payroll') END;
END;
